void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec3 resolution = iResolution;

    mat3 matriceCamera = mat3(
        0.3, 0.1, 0.1,
        0.1, -0.3, 1.0,
        -0.09, 0.2, 1.0
    );

    vec3 directionRayon = vec3((coordFragment * 3.0 - resolution.xy) / resolution.y, 0.5) * matriceCamera;
    vec3 positionEspace = vec3(0.0, -8.0, 0.5);
    vec3 coordonneesLog;

    couleurFragment = vec4(-0.5);

    float distanceLog;
    float distanceEstimee;

    for (float iteration = 0.0; iteration < 50.0; iteration++) {
        distanceLog = length(positionEspace);

        coordonneesLog = vec3(
            fract((log(distanceLog) - iTime * 0.5) * 0.2) * 6.0,
            exp(-positionEspace.y / distanceLog * 1.1),
            atan(positionEspace.z, positionEspace.x)
        );

        distanceEstimee = max(
            coordonneesLog.y - 0.8 
            - abs(dot(sin(coordonneesLog.yzx * 2.0), cos(coordonneesLog * 11.0))) * 0.13 
            - abs(dot(sin(coordonneesLog.yzx * 160.0), cos(coordonneesLog * 1120.0))) * 0.000125, 
            0.0
        );

        vec3 couleurEtape = (0.5 + 0.2 * cos(distanceLog * 0.5 + iTime * 0.3 + vec3(1.0, 3.0, 5.0))) * 0.04;
        couleurFragment.xyz += min(0.3 - couleurFragment.xyz, distanceEstimee * 3.0) * couleurEtape;

        positionEspace += directionRayon * distanceEstimee * distanceLog * 0.2;
    }

    couleurFragment.xyz *= couleurFragment.xyz / (couleurFragment.xyz * (couleurFragment.xyz + 0.4) + 0.2);
    couleurFragment.w = 1.0;
}
